function preLoader() {

    let loader = document.querySelector(".preLoader");
    let site = document.querySelector(".site");

    // thori der loader chale (e.g. 2 seconds)
    setTimeout(() => {

        loader.style.transition = "0.6s ease";
        loader.style.opacity = "0";

        setTimeout(() => {
            loader.style.display = "none";
            site.style.opacity = "1";
        }, 600);

    }, 2000); // ⏱ time adjust here
}


//  CUSTOM MOUSE CURSOR

function mouseCursor() {
    if (document.querySelector(".cursor-inner") || document.querySelector(".cursor-outer")) {
        const cursorInner = document.querySelector(".cursor-inner");
        const cursorOuter = document.querySelector(".cursor-outer");
        let mouseX = 0;
        let mouseY = 0;
        let isHovering = false;

        window.addEventListener("mousemove", function (event) {
            if (!isHovering) {
                gsap.to(cursorOuter, {
                    x: event.clientX,
                    y: event.clientY,
                });
            }
            gsap.to(cursorInner, {
                x: event.clientX,
                y: event.clientY,
            });
            mouseY = event.clientY;
            mouseX = event.clientX;
        });

        const elementsToTrack = document.querySelectorAll("a, img, .cursor-pointer");
        elementsToTrack.forEach((element) => {
            element.addEventListener("mouseenter", function () {
                cursorInner.classList.add("cursor-hover");
                cursorOuter.classList.add("cursor-hover");
                isHovering = true;
            });

            element.addEventListener("mouseleave", function () {
                if (!(
                    element.tagName === "A" ||
                    element.tagName === "IMG" ||
                    element.closest(".cursor-pointer")
                )) {
                    cursorInner.classList.remove("cursor-hover");
                    cursorOuter.classList.remove("cursor-hover");
                }
                isHovering = false;
            });
        });

        gsap.set(cursorInner, {
            visibility: "visible"
        });
        gsap.set(cursorOuter, {
            visibility: "visible"
        });
    }
}

// ANCHOR VOID MANIPULATE #

function replaceHash() {
    document.querySelectorAll("a").forEach((a) => {
        let href = a.getAttribute("href");
        a.href = href ?
            href.startsWith("#") && href.endsWith("#") ?
                href.replace("#", "javascript:;") :
                href :
            "javascript:;";
    });
}

// GSAP IMAGE REVEAL ANIMATION


gsap.registerPlugin(ScrollTrigger);

// LEFT elements
gsap.utils.toArray(".left").forEach((el) => {
    gsap.from(el, {
        x: -300,
        opacity: 0,
        ease: "power2.out",
        scrollTrigger: {
            trigger: el,
            start: "top 85%",
            end: "top 30%",
            scrub: 1
        }
    });
});

// RIGHT elements
gsap.utils.toArray(".right").forEach((el) => {
    gsap.from(el, {
        x: 300,
        opacity: 0,
        ease: "power2.out",
        scrollTrigger: {
            trigger: el,
            start: "top 85%",
            end: "top 30%",
            scrub: 1
        }
    });
});


function headingAnimation() {
    const heading = document.querySelectorAll(".mainHead");

    heading.forEach((text) => {
        let text1 = new SplitType(text, {
            types: "chars",
        });
        const headingTl = gsap.timeline({
            scrollTrigger: {
                trigger: text,
                toggleActions: "play none none reset",
            },
        });
        let chars = text.querySelectorAll(`.mainHead .char`);
        headingTl.from(chars, 1, {
            x: 50,
            autoAlpha: 0,
            stagger: 0.1,
            webkitFilter: "blur(20px)",
            ease: "power4.out",
        });
    });
}


// LENIS SETUP

function lenissetup() {
    const lenis = new Lenis()
    window.lenis = lenis;

    function raf(time) {
        lenis.raf(time)
        requestAnimationFrame(raf)
    }
    requestAnimationFrame(raf)
}

// SMOOTH SCROLL FOR IN-PAGE ANCHOR LINKS (no # added to the URL)

function smoothAnchorScroll() {
    document.querySelectorAll('a[href^="#"]').forEach((link) => {
        const hash = link.getAttribute("href");
        if (!hash || hash.length < 2) return;

        const target = document.querySelector(hash);
        if (!target) return;

        link.addEventListener("click", function (e) {
            e.preventDefault();
            if (window.lenis) {
                window.lenis.scrollTo(target);
            } else {
                target.scrollIntoView({ behavior: "smooth", block: "start" });
            }
        });
    });
}

// Function Initialization
function initializeFunctions() {
    preLoader();
    allSliders();
    mouseCursor();
    replaceHash();
    // LENIS
    lenissetup();
    smoothAnchorScroll();
    headingAnimation();
    // AOS INIT
    AOS.init({
        duration: 1200,
        disable: 'mobile'
    });
}


// Event listener for window load
window.addEventListener("load", initializeFunctions);

