document.addEventListener("DOMContentLoaded", function () {
    if (typeof gsap === 'undefined') return;

    const tickerContent = document.querySelector('.services-page-ticker-content');
    if (tickerContent) {
        const wrapper = document.querySelector('.services-page-ticker-wrapper');
        const clone = tickerContent.cloneNode(true);
        wrapper.appendChild(clone);

        function initTicker() {
            gsap.killTweensOf(wrapper);
            const contentWidth = tickerContent.offsetWidth;

            gsap.set(wrapper, { x: 0 });
            gsap.to(wrapper, {
                x: -contentWidth,
                ease: "none",
                duration: contentWidth / 80,
                repeat: -1
            });
        }

        if (document.fonts && document.fonts.ready) {
            document.fonts.ready.then(function () {
                initTicker();
            });
        } else {
            window.addEventListener('load', initTicker);
        }

        let resizeTimer;
        window.addEventListener('resize', function () {
            clearTimeout(resizeTimer);
            resizeTimer = setTimeout(initTicker, 250);
        });
    }
});


document.addEventListener('DOMContentLoaded', function() {
    const colorButtons = document.querySelectorAll('.color-btn');
    const colorNameEl = document.querySelector('.slectric-bike-color-name');
    
    // Color names mapping
    const colorNames = {
        white: 'Matte White',
        black: 'Matte Black',
        red: 'Racing Red',
        silver: 'Silver Chrome',
        blue: 'Midnight Blue'
    };
    
    colorButtons.forEach(btn => {
        btn.addEventListener('click', function() {
            // Remove active class from all buttons
            colorButtons.forEach(b => b.classList.remove('active'));
            
            // Add active class to clicked button
            this.classList.add('active');
            
            // Update color name
            const color = this.dataset.color;
            if (colorNameEl && colorNames[color]) {
                colorNameEl.textContent = colorNames[color];
            }
        });
    });
});


