        // shop page pagination
document.addEventListener('DOMContentLoaded', function() {

    // ========================================
    // PAGINATION - 3 Products per Row
    // ========================================

    const products = document.querySelectorAll('.product-item');
    const paginationContainer = document.getElementById('paginationContainer');
    const displayCountEl = document.getElementById('displayCount');

    const itemsPerPage = 6; // 2 rows × 3 columns
    let currentPage = 1;
    const totalProducts = products.length;
    const totalPages = Math.ceil(totalProducts / itemsPerPage);

    // Function to show products for current page
    function showPage(page) {
        const start = (page - 1) * itemsPerPage;
        const end = start + itemsPerPage;

        products.forEach((product, index) => {
            if (index >= start && index < end) {
                product.classList.remove('hidden');
                product.style.display = 'block';
                product.style.animation = 'fadeInUp 0.5s ease forwards';
            } else {
                product.classList.add('hidden');
                product.style.display = 'none';
                product.style.animation = 'none';
            }
        });

        // Update display count
        const visibleItems = document.querySelectorAll('.product-item:not(.hidden)').length;
        if (displayCountEl) {
            displayCountEl.textContent = visibleItems;
        }

        // Update pagination active state
        document.querySelectorAll('.slectric-bike-page-item[data-page]').forEach(btn => {
            btn.classList.remove('active');
            if (btn.dataset.page == page) {
                btn.classList.add('active');
            }
        });

        // Update prev/next buttons
        const prevBtn = document.querySelector('.prev-page');
        const nextBtn = document.querySelector('.next-page');
        
        if (prevBtn) {
            if (page === 1) {
                prevBtn.classList.add('disabled');
            } else {
                prevBtn.classList.remove('disabled');
            }
        }
        
        if (nextBtn) {
            if (page === totalPages) {
                nextBtn.classList.add('disabled');
            } else {
                nextBtn.classList.remove('disabled');
            }
        }

        currentPage = page;
    }

    // Generate pagination buttons
    function generatePagination() {
        const existingButtons = paginationContainer.querySelectorAll('.slectric-bike-page-item:not(.prev-page):not(.next-page)');
        existingButtons.forEach(btn => btn.remove());

        const prevBtn = paginationContainer.querySelector('.prev-page');
        const nextBtn = paginationContainer.querySelector('.next-page');

        for (let i = 1; i <= totalPages; i++) {
            const pageBtn = document.createElement('a');
            pageBtn.href = '#';
            pageBtn.className = `slectric-bike-page-item${i === 1 ? ' active' : ''}`;
            pageBtn.dataset.page = i;
            pageBtn.textContent = i;
            
            pageBtn.addEventListener('click', function(e) {
                e.preventDefault();
                const pageNum = parseInt(this.dataset.page);
                if (pageNum !== currentPage) {
                    showPage(pageNum);
                    document.querySelector('.slectric-bike-grid').scrollIntoView({
                        behavior: 'smooth',
                        block: 'start'
                    });
                }
            });

            paginationContainer.insertBefore(pageBtn, nextBtn);
        }
    }

    // Setup navigation buttons
    function setupNavButtons() {
        const prevBtn = document.querySelector('.prev-page');
        const nextBtn = document.querySelector('.next-page');

        if (prevBtn) {
            prevBtn.addEventListener('click', function(e) {
                e.preventDefault();
                if (currentPage > 1) {
                    showPage(currentPage - 1);
                    document.querySelector('.slectric-bike-grid').scrollIntoView({
                        behavior: 'smooth',
                        block: 'start'
                    });
                }
            });
        }

        if (nextBtn) {
            nextBtn.addEventListener('click', function(e) {
                e.preventDefault();
                if (currentPage < totalPages) {
                    showPage(currentPage + 1);
                    document.querySelector('.slectric-bike-grid').scrollIntoView({
                        behavior: 'smooth',
                        block: 'start'
                    });
                }
            });
        }
    }

    // Initialize
    if (paginationContainer && products.length > 0) {
        generatePagination();
        setupNavButtons();
        showPage(1);
    }

    // ========================================
    // COLOR BUTTONS
    // ========================================

    const colorButtons = document.querySelectorAll('.color-btn');
    colorButtons.forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.stopPropagation();
            
            const colorWrap = this.closest('.slectric-bike-color-wrap');
            if (!colorWrap) return;
            
            const siblings = colorWrap.querySelectorAll('.color-btn');
            siblings.forEach(b => b.classList.remove('active'));
            
            this.classList.add('active');
            
            const colorName = colorWrap.querySelector('.slectric-bike-color-name');
            if (colorName) {
                const colorMap = {
                    white: 'Matte White',
                    black: 'Matte Black',
                    red: 'Racing Red',
                    silver: 'Silver Chrome',
                    blue: 'Midnight Blue'
                };
                const color = this.dataset.color;
                colorName.textContent = colorMap[color] || color;
            }
        });
    });

    // ========================================
    // ADD TO CART BUTTONS
    // ========================================

    const cartBtns = document.querySelectorAll('.slectric-bike-cart-btn');
    cartBtns.forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.stopPropagation();
            
            const originalHTML = this.innerHTML;
            this.innerHTML = '✓';
            this.style.background = '#00a86b';
            this.style.transform = 'scale(0.9)';
            
            setTimeout(() => {
                this.innerHTML = originalHTML;
                this.style.background = 'linear-gradient(135deg, #d81111, #b00f0f)';
                this.style.transform = 'scale(1)';
            }, 1500);
        });
    });

});